// Family Head / Adult Member dashboard per docs/Three_Portal_Feature_Spec.md §"Family Head dashboard" / "Adult dashboard".
// No AI on this screen. GET /dashboard/family; layout chosen by the returned `role`.
import { useCallback, useEffect, useState } from 'react'
import { Link } from 'react-router-dom'

import { EmptyState, ErrorState, LoadingState } from '../../components/shared/ViewState'
import { threePortalApi, type FamilyDashboardSummaryDto } from '../../services/apiClient'
import { formatDateTime, friendlyStatusLabel } from './threePortalShared'

export function FamilyDashboardPanel() {
  const [data, setData] = useState<FamilyDashboardSummaryDto | null>(null)
  const [status, setStatus] = useState<'loading' | 'ready' | 'error'>('loading')

  const load = useCallback(async () => {
    setStatus('loading')
    try {
      const { data: dashboard } = await threePortalApi.getFamilyDashboard()
      setData(dashboard)
      setStatus('ready')
    } catch {
      setStatus('error')
    }
  }, [])

  useEffect(() => {
    void load()
  }, [load])

  if (status === 'loading') return <LoadingState label="Loading your family dashboard" />
  if (status === 'error') return <ErrorState message="Dashboard summary could not be loaded." onRetry={() => void load()} />
  if (!data) return <EmptyState title="No dashboard data" message="Nothing to show yet." />

  const isHead = data.role === 'Head'

  return (
    <div className="page-stack" aria-label="Family dashboard">
      <section className="metric-grid" aria-label="Family metrics">
        <article className="metric-card metric-card--teal">
          <span>Members</span>
          <strong>{data.memberCount}</strong>
          <small>{data.minorCount} minor{data.minorCount === 1 ? '' : 's'}</small>
        </article>
        <article className="metric-card metric-card--blue">
          <span>Next appointment</span>
          <strong>{data.nextAppointment ? formatDateTime(data.nextAppointment.startsAt) : 'None scheduled'}</strong>
          <small>{data.nextAppointment ? friendlyStatusLabel(data.nextAppointment.status) : 'Book when needed'}</small>
        </article>
        <article className="metric-card metric-card--amber">
          <span>Open cases</span>
          <strong>{data.openCases}</strong>
          <small>{data.approvedGuidanceCount} approved guidance</small>
        </article>
        {isHead && (
          <article className="metric-card">
            <span>Join requests</span>
            <strong>{data.pendingJoinRequests ?? 0}</strong>
            <small>Awaiting your review</small>
          </article>
        )}
      </section>

      <section className="panel">
        <h2>My Family Doctor</h2>
        {data.familyDoctor ? (
          <p>
            <strong>{data.familyDoctor.displayName}</strong>
            {data.familyDoctor.specialty ? ` · ${data.familyDoctor.specialty}` : ''}
            {data.familyDoctor.clinic ? ` · ${data.familyDoctor.clinic}` : ''}
          </p>
        ) : (
          <EmptyState title="No family doctor yet" message="Search the directory and send a request." />
        )}
        <Link className="button button--secondary" to="/my-doctor">
          {isHead ? 'Manage family doctor' : 'View family doctor'}
        </Link>
      </section>

      {isHead && (data.pendingJoinRequests ?? 0) > 0 && (
        <section className="panel" aria-label="Needs attention">
          <h2>Needs attention</h2>
          <p>{data.pendingJoinRequests} pending join request{(data.pendingJoinRequests ?? 0) === 1 ? '' : 's'} waiting for your decision.</p>
          <Link className="button button--primary" to="/join-family">Review join requests</Link>
        </section>
      )}

      <section className="panel">
        <h2>Quick actions</h2>
        <div className="action-grid">
          {isHead && (
            <>
              <Link className="action-card" to="/family">Add minor</Link>
              <Link className="action-card" to="/family">Invite adult</Link>
              <Link className="action-card" to="/records">Upload report</Link>
              <Link className="action-card" to="/triage">Report symptoms</Link>
            </>
          )}
          <Link className="action-card" to="/appointments">Book appointment</Link>
        </div>
      </section>

      <section className="panel">
        <h2>Recent activity</h2>
        {data.recentActivity.length === 0 ? (
          <EmptyState title="No recent activity" message="Activity for you and your minors will appear here." />
        ) : (
          <ul className="activity-list">
            {data.recentActivity.map((entry) => (
              <li key={entry.id}>
                <span>{entry.description}</span>
                <small>{formatDateTime(entry.createdAt)}</small>
              </li>
            ))}
          </ul>
        )}
      </section>
    </div>
  )
}
